import os,json,subprocess
from pathlib import Path
src=Path("/srv/projects/codex-agent");dst=Path("/srv/projects/Codex")
old_bridge=Path("/home/ubuntu/codex-bridge");archive=dst/"archive";new_bridge=archive/"legacy-bridge"
home_agent=Path("/home/ubuntu/codex-agent")
out={"project":"Codex","status":"BLOCKED","changed":False}
def services():
 names=("ssh","nginx","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root")
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip() for n in names}
moved_agent=False;moved_bridge=False
try:
 if not src.is_dir() or src.is_symlink() or not old_bridge.is_dir() or old_bridge.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("preflight_directories")
 if not home_agent.is_symlink() or home_agent.resolve(strict=True)!=src:raise RuntimeError("codex_agent_alias_mismatch")
 if src.stat().st_dev!=dst.parent.stat().st_dev or src.stat().st_dev!=old_bridge.stat().st_dev:raise RuntimeError("not_same_filesystem")
 if not (src/"package.json").is_file() or not (src/"node_modules").is_dir():raise RuntimeError("agent_package_not_recognized")
 expected=[(src.stat().st_dev,src.stat().st_ino,src.stat().st_uid,src.stat().st_gid),(old_bridge.stat().st_dev,old_bridge.stat().st_ino,old_bridge.stat().st_uid,old_bridge.stat().st_gid)]
 for p in Path("/proc").iterdir():
  if not p.name.isdigit():continue
  for link in ("cwd","exe"):
   try:
    v=os.readlink(str(p/link))
    if any(v==str(x) or v.startswith(str(x)+"/") for x in (src,old_bridge)):raise RuntimeError("codex_runtime_active")
   except (OSError,PermissionError):pass
 baseline=services()
 os.rename(src,dst);moved_agent=True
 os.symlink(str(dst),src)
 archive.mkdir(mode=0o700)
 os.chown(archive,expected[0][2],expected[0][3])
 os.rename(old_bridge,new_bridge);moved_bridge=True
 os.symlink(str(new_bridge),old_bridge)
 after=[(dst.stat().st_dev,dst.stat().st_ino,dst.stat().st_uid,dst.stat().st_gid),(new_bridge.stat().st_dev,new_bridge.stat().st_ino,new_bridge.stat().st_uid,new_bridge.stat().st_gid)]
 if after!=expected or not src.is_symlink() or src.resolve(strict=True)!=dst or home_agent.resolve(strict=True)!=dst or old_bridge.resolve(strict=True)!=new_bridge or services()!=baseline:raise RuntimeError("postcheck_failed")
 out.update(status="MOVED_VERIFIED",changed=True,physical_root=str(dst),legacy_bridge_archived_inside=True,old_paths_are_aliases=True,owners_inodes_preserved=True,services_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:140]
 try:
  if old_bridge.is_symlink() and old_bridge.resolve(strict=False)==new_bridge:old_bridge.unlink()
  if moved_bridge and new_bridge.is_dir() and not old_bridge.exists():os.rename(new_bridge,old_bridge)
  if archive.is_dir() and not list(archive.iterdir()):archive.rmdir()
  if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
  if moved_agent and dst.is_dir() and not src.exists():os.rename(dst,src)
 except Exception:out["rollback"]="INCOMPLETE"
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_VERIFIED":raise SystemExit(3)
